declare const DEFAULT_MAX_DEPTH = 100;
interface LoadOptions {
    maxDepth?: number;
}
declare const load: (toml: string, options?: LoadOptions) => Record<string, unknown>;

/** Thrown for any input that is not valid TOML, including by `TomlTime`. */
declare class SyntaxParseError extends Error {
    constructor(message: string);
}

interface DumpOptions {
    /**
     * The newline sequence.
     * @default '\n'
     */
    newline?: '\n' | '\r\n';
    /**
     * If true, properties with unsupported types (like undefined, Symbol, Function)
     * will be silently ignored instead of throwing an error.
     * @default false
     */
    ignoreUndefined?: boolean;
    /**
     * If true, string keys will always be quoted, even when they contains only
     * bare-key characters.
     * @default false
     */
    forceQuotes?: boolean;
}

declare function dump(obj: Record<string, unknown>, options?: DumpOptions): string;

/** Which of TOML's three date/time types produced a `TomlDate`. */
type TomlDateKind = 'offset-date-time' | 'local-date-time' | 'local-date';
/**
 * A `Date` that remembers which TOML type produced it. All three map onto one
 * instant in JavaScript, so without this `dump(load(x))` re-emits a local
 * date-time as `...Z`, asserting an offset the author never wrote.
 */
declare class TomlDate extends Date {
    #private;
    constructor(value: string, kind?: TomlDateKind);
    /**
     * Which TOML form this was written in, and only that: not the offset it
     * carried, nor precision below a millisecond. An accessor rather than an own
     * property, so deep-equality treats an instance exactly like a `Date`.
     */
    get kind(): TomlDateKind;
    /**
     * The form the document wrote, so a local date-time does not claim a `Z` it
     * never carried. `toJSON` delegates here, which is what keeps
     * `JSON.stringify` and every external consumer honest, not only `dump()`.
     */
    toISOString(): string;
}

/**
 * A TOML local time: a wall clock, not an instant. It extends `Date` so that
 * generic value walkers, which reach for `instanceof Date` and have no branch
 * for anything else, see it. Read it with `toISOString()` or the `getUTC*`
 * accessors; the underlying instant is anchored on an arbitrary day.
 */
declare class TomlTime extends Date {
    #private;
    /** Throws `SyntaxParseError` unless `raw` is a TOML local time. */
    constructor(raw: string);
    get hour(): number;
    get minute(): number;
    get second(): number;
    /** Fractional seconds including the dot, or `''`. Never rounded. */
    get fraction(): string;
    /**
     * The time of day, not an instant: `07:32:00.123456789`. Overriding this
     * also fixes `toJSON`, which delegates here, so `JSON.stringify` and any
     * consumer reading a `Date` sees the time the document actually wrote.
     */
    toISOString(): string;
    /**
     * `Date`'s version would render the anchor day in the host timezone, so
     * `13:37` prints as `06:37` in Edmonton. There is no day here to render,
     * which is why this one type overrides it and `TomlDate` does not.
     */
    toString(): string;
}

export { DEFAULT_MAX_DEPTH, type LoadOptions, SyntaxParseError, TomlDate, type TomlDateKind, TomlTime, dump, load };
